/*
 * allen-audio.js: Allen's startup sound, the one the iMac plays as its two
 * black holes merge. Generated by om/allen-audio (Omega); do not edit.
 *
 * The sound is ../audio/allen-chirp.wav, written sample for sample by
 * om/allen-audio/chirp.om, a port of aienux native/kernel/ui/chirp.c at
 * da55660ea7337f2b6a42095fcd1fb6ddebe1cc7c. It holds frames 545280 to 590400
 * of the night at 48000 Hz, 16-bit mono (the native left and right samples
 * are equal): 11360 ms to 12300 ms of the night, the merger at 12000 ms.
 * This script only plays it.
 *
 * window.AllenAudio
 *   enter(arg)     call inside a click or key press. The only place an audio
 *                  context is created or resumed. arg is a scene kind or
 *                  { kind, nightMs }. The native source has one sound, the
 *                  merger chirp of the two-hole night (kind 'night', alias
 *                  'home', the default); any other kind (the /allen/ tube
 *                  included) has no native sound and resolves false without
 *                  touching audio. nightMs is where the night is at the moment
 *                  of the call (default 0: the night starts now). As on the
 *                  iMac, the sound lands on the merger:
 *                  before 11360 ms it waits, inside the chirp it starts from
 *                  that moment, after 12300 ms nothing plays. While a sound
 *                  is pending or playing, enter returns the same promise;
 *                  after it ends or stops, the next gesture may enter again
 *                  (a replay). Resolves true once the sound is scheduled,
 *                  false when muted, unsupported, stopped or too late; never
 *                  rejects.
 *   pause()        suspends the audio context: its clock and the sound
 *                  freeze together, as the scene's clock does. Done by
 *                  itself when the page is hidden, so no chirp plays in the
 *                  background.
 *   resume()       resumes a context pause() suspended (the scene calls it
 *                  when it runs again); never creates one, and does nothing
 *                  while muted.
 *   stop()         stops the sound and closes the audio context; done by
 *                  itself on pagehide. Call it when the scene is destroyed
 *                  or replayed.
 *   setMuted(b)    stores the choice in localStorage 'allen.audio.muted'
 *                  ('1' or '0'), the only key this script writes; muting
 *                  stops the sound.
 *   muted()        the stored choice.
 * data-chirp-src on this script's tag points elsewhere (resolved against the
 * page); by default the file sits beside this script's folder, so the same
 * bytes work on aienos.com and on a localhost install.
 */
(function () {
  'use strict';
  var KEY = 'allen.audio.muted';
  var RATE = 48000;
  var FRAMES = 45120;
  var START_MS = 11360;
  var MERGE_MS = 12000;
  var END_MS = 12300;

  var me = document.currentScript;
  var pick = me && me.getAttribute('data-chirp-src');
  var src = pick ? new URL(pick, location.href).href
    : new URL('../audio/allen-chirp.wav', (me && me.src) || location.href).href;

  var ctx = null;
  var node = null;
  var entered = null;
  var paused = false;
  var pausedAt = 0;
  var pausedMs = 0;

  function stored() {
    try { return window.localStorage.getItem(KEY) === '1'; } catch (e) { return false; }
  }
  var isMuted = stored();

  function close() {
    var n = node;
    var c = ctx;
    node = null;
    ctx = null;
    entered = null;
    paused = false;
    if (n) {
      n.onended = null;
      try { n.stop(); } catch (e) { /* not started yet */ }
      n.disconnect();
    }
    if (c && c.close && c.state !== 'closed') c.close().then(null, function () {});
  }

  function word(v, at) { return v.getUint32(at, true); }
  function half(v, at) { return v.getUint16(at, true); }

  /* The asset's exact header, or nothing: mono 16-bit PCM at RATE, FRAMES long. */
  function pcm(bytes) {
    if (bytes.byteLength !== 44 + 2 * FRAMES) return null;
    var v = new DataView(bytes);
    if (word(v, 0) !== 0x46464952 || word(v, 4) !== 36 + 2 * FRAMES || word(v, 8) !== 0x45564157 ||
        word(v, 12) !== 0x20746d66 || word(v, 16) !== 16 || half(v, 20) !== 1 || half(v, 22) !== 1 ||
        word(v, 24) !== RATE || word(v, 28) !== 2 * RATE || half(v, 32) !== 2 || half(v, 34) !== 16 ||
        word(v, 36) !== 0x61746164 || word(v, 40) !== 2 * FRAMES) return null;
    var out = new Float32Array(FRAMES);
    for (var i = 0; i < FRAMES; i++) out[i] = v.getInt16(44 + 2 * i, true) / 32768;
    return out;
  }

  /* A silent frame started inside the gesture: some browsers unlock output only so. */
  function unlock(c) {
    try {
      var s = c.createBufferSource();
      s.buffer = c.createBuffer(1, 1, c.sampleRate);
      s.connect(c.destination);
      s.start(0);
    } catch (e) { /* the real sound still tries */ }
  }

  function play(c, samples, night) {
    if (c !== ctx || isMuted || night >= END_MS) return false;
    var buf = c.createBuffer(1, FRAMES, RATE);
    buf.getChannelData(0).set(samples);
    var n = c.createBufferSource();
    n.buffer = buf;
    n.connect(c.destination);
    n.onended = function () { if (node === n) close(); };
    node = n;
    if (night < START_MS) n.start(c.currentTime + (START_MS - night) / 1000);
    else n.start(0, (night - START_MS) / 1000);
    return true;
  }

  var KINDS = { night: 1, home: 1 };

  function enter(arg) {
    var opts = typeof arg === 'string' ? { kind: arg } : arg || {};
    if (!KINDS.hasOwnProperty(opts.kind || 'night')) return Promise.resolve(false);
    if (entered) return entered;
    var t0 = performance.now();
    pausedMs = 0;
    var base = typeof opts.nightMs === 'number' && opts.nightMs >= 0 ? opts.nightMs : 0;
    var AC = window.AudioContext || window.webkitAudioContext;
    if (isMuted || !AC || !window.fetch || base >= END_MS) return Promise.resolve(false);
    var c;
    try { c = new AC(); } catch (e) { return Promise.resolve(false); }
    ctx = c;
    if (c.resume) c.resume().then(null, function () {});
    unlock(c);
    entered = fetch(src, { credentials: 'same-origin' })
      .then(function (r) {
        if (!r.ok) throw new Error('allen-chirp.wav ' + r.status);
        return r.arrayBuffer();
      })
      .then(function (bytes) {
        var samples = pcm(bytes);
        var held = pausedMs + (paused ? performance.now() - pausedAt : 0);
        var ok = samples ? play(c, samples, base + performance.now() - t0 - held) : false;
        if (!ok && ctx === c) close();
        return ok;
      })
      .then(null, function () {
        if (ctx === c) close();
        return false;
      });
    return entered;
  }

  function pause() {
    if (!ctx || paused) return;
    paused = true;
    pausedAt = performance.now();
    if (ctx.suspend) ctx.suspend().then(null, function () {});
  }

  function resume() {
    if (!ctx || !paused || isMuted) return;
    paused = false;
    pausedMs += performance.now() - pausedAt;
    if (ctx.resume) ctx.resume().then(null, function () {});
  }

  function setMuted(on) {
    isMuted = !!on;
    try { window.localStorage.setItem(KEY, isMuted ? '1' : '0'); } catch (e) { /* kept for this page */ }
    if (isMuted) close();
  }

  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') pause();
  });
  window.addEventListener('pagehide', close);

  window.addEventListener('storage', function (e) {
    if (e.key !== KEY) return;
    isMuted = e.newValue === '1';
    if (isMuted) close();
  });

  window.AllenAudio = Object.freeze({
    enter: enter,
    stop: close,
    pause: pause,
    resume: resume,
    setMuted: setMuted,
    muted: function () { return isMuted; },
    src: src,
    kinds: Object.freeze(['night', 'home']),
    timeline: Object.freeze({ rate: RATE, frames: FRAMES, startMs: START_MS, mergeMs: MERGE_MS, endMs: END_MS })
  });
})();
